 1| /**
 2|  * compute-tax (inside the tax sub-flowchart): the tax on the amount, rounded
 3|  * to the cent.
 4|  *
 5|  * Example: amount 450 at 0.08 → `tax = 36`.
 6|  */
 7| import { roundCents } from '../../../../money.mjs';
 8| 
 9| export const purpose = 'Work out the tax on the amount.';
10| 
11| /** @param {any} scope */
12| export function run(scope) {
13|   scope.tax = roundCents(scope.amount * scope.rate);
14| }
