 1| /**
 2|  * The tax sub-flowchart: wiring only. Rate first, then the tax.
 3|  *
 4|  *   find-rate → compute-tax
 5|  */
 6| import { flowChart } from 'footprintjs';
 7| 
 8| import * as computeTax from './steps/compute-tax/index.mjs';
 9| import * as findRate from './steps/find-rate/index.mjs';
10| 
11| export const purpose = 'Work out the sales tax for the region the order ships to.';
12| 
13| /** Builds the tax sub-flowchart. */
14| export function buildTaxChart() {
15|   return flowChart('Find rate', findRate.run, 'find-rate', { description: findRate.purpose })
16|     .addFunction('Compute tax', computeTax.run, 'compute-tax', computeTax.purpose)
17|     .build();
18| }
